/*
 * A343180  Trajectory of 1 under the morphism 1 -> 12, 2 -> 32, 3 -> 14, 4 ->
 *          34.
 * https://oeis.org/A343180
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth symbol in the infinite word generated by the
 *            morphism 1 → 12, 2 → 32, 3 → 14, 4 → 34. The computation is done
 *            by following the binary representation of n: starting from the
 *            root symbol 1, for each bit from most significant to least
 *            significant we replace the current symbol by the...
 * Range:     u8 n <= 94, u16 n <= 94, u32 n <= 94, u64 n <= 94, u128 n <= 94,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* *** Function definition required by the build environment ***
   external linkage:  seq_t a(idx_t n)  */
seq_t a(idx_t n)
{
    /* Base case: the very first symbol is 1. */
    if (n == 0) {
        return (seq_t)1;
    }

    /* Determine the index of the most significant bit of n. */
    idx_t msb = 0;
    idx_t t = n;
    while (t > 1) {
        t >>= 1;
        msb++;
    }

    /* Mapping tables for left (bit 0) and right (bit 1) child. */
    static const idx_t left[5]  = { 0, 1, 3, 1, 3 };
    static const idx_t right[5] = { 0, 2, 2, 4, 4 };

    idx_t digit = 1;   /* start with the root symbol */

    /* Process bits from most significant to least significant. */
    for (idx_t i = msb; ; i--) {
        /* Bit of n at position i. */
        if (n & (idx_t)1 << i) {
            digit = right[digit];
        } else {
            digit = left[digit];
        }

        if (i == 0) {
            break;
        }
    }

    return (seq_t)digit;
}
